"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  scrollUnits,
  type ScrollMotionProps,
  type ScrollEntranceOptions,
  type ScrollItem,
} from "./scroll-shared";
import { scrollEase, scrollStagger, scrollRandom } from "./scroll-math";
export interface RandomRotateProps extends ScrollMotionProps, ScrollEntranceOptions {
  items: readonly ScrollItem[];
  min?: number;
  max?: number;
  seed?: number;
  stagger?: number;
  overlap?: number;
}
export function RandomRotate({
  items,
  min = -14,
  max = 14,
  seed = 1,
  stagger = 0.4,
  overlap = 35,
  trigger = "enter",
  ...props
}: RandomRotateProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    { ...props, trigger },
    ({ progress: p, reduced }) => {
      scrollUnits(root.current!).forEach((el, i) => {
        const q = scrollEase(scrollStagger(p, i, items.length, stagger)),
          angle = min + (max - min) * scrollRandom(i, seed);
        el.style.opacity = String(q);
        el.style.transform = `translateY(${reduced ? 0 : (1 - q) * 50}px) rotate(${angle * q}deg) scale(${0.86 + 0.14 * q})`;
      });
    },
    `${items.map((x) => x.id).join(",")}:${min}:${max}:${seed}:${stagger}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="random-rotate"
      className={props.className}
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        height: "100%",
        padding: "12% 8%",
        ...props.style,
      }}
    >
      {items.map((item, i) => (
        <div
          data-scroll-unit={item.id}
          key={item.id}
          className={item.className}
          style={{
            position: "relative",
            zIndex: i === Math.floor(items.length / 2) ? 2 : 1,
            width: `${100 / Math.max(1, items.length)}%`,
            aspectRatio: 0.75,
            marginLeft: i ? `-${Math.min(60, overlap) / Math.max(1, items.length)}%` : 0,
            overflow: "hidden",
            borderRadius: 10,
            boxShadow: "0 18px 35px #0002",
            ...item.style,
          }}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}
